import io
import os
import shutil
import subprocess
import sys

import click
import click._termui_impl as ti

try:
    import click._compat as compat
except Exception:  # pragma: no cover
    compat = None

TEXT = "plain \x1b[31mred\x1b[0m end"
CALLS = []
UNSET = object()


class FakeStdin:
    def __init__(self):
        self.parts = []
        self.closed = False

    def write(self, s):
        if isinstance(s, bytes):
            s = s.decode("utf-8", "replace")
        self.parts.append(s)
        return len(s)

    def flush(self):
        pass

    def close(self):
        self.closed = True


class FakePopen:
    def __init__(self, args, *a, **kw):
        self.stdin = FakeStdin()
        self.stdout = None
        self.stderr = None
        self.returncode = 0
        self.pid = 0
        if isinstance(args, (list, tuple)):
            argv = [str(x) for x in args]
        else:
            argv = [str(args)]
        CALLS.append({"argv": argv, "env": kw.get("env"), "stdin": self.stdin})

    def wait(self, *a, **k):
        return 0

    def poll(self):
        return 0

    def terminate(self):
        pass

    def kill(self):
        pass

    def communicate(self, *a, **k):
        return (None, None)

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        return False


class TTYOut(io.StringIO):
    def isatty(self):
        return True


class TTYIn(io.StringIO):
    def isatty(self):
        return True


FAKE_OUT = TTYOut()


def fake_which(cmd, *a, **k):
    return "/usr/bin/" + os.path.basename(str(cmd))


def _true(*a, **k):
    return True


# Deterministic sandbox: no real pager, both ends look like a terminal.
subprocess.Popen = FakePopen
shutil.which = fake_which
if hasattr(ti, "which"):
    ti.which = fake_which
if hasattr(ti, "isatty"):
    ti.isatty = _true
if compat is not None and hasattr(compat, "isatty"):
    compat.isatty = _true
if hasattr(ti, "_default_text_stdout"):
    ti._default_text_stdout = lambda: FAKE_OUT
sys.stdin = TTYIn()


def fmt_less(v):
    return "UNSET" if v is UNSET else repr(v)


def run(less, pager, color):
    CALLS.clear()
    FAKE_OUT.seek(0)
    FAKE_OUT.truncate(0)
    os.environ.pop("LESS", None)
    if less is not UNSET:
        os.environ["LESS"] = less
    os.environ["PAGER"] = pager
    os.environ["TERM"] = "xterm"
    err = None
    try:
        click.echo_via_pager(TEXT, color=color)
    except Exception as e:
        err = f"{type(e).__name__}: {e}"

    head = f"LESS={fmt_less(less)} PAGER={pager!r} color={color!r}"
    parts = [head]
    if err is not None:
        parts.append(f"error={err}")
    if not CALLS:
        parts.append("popen=NONE")
    for i, c in enumerate(CALLS):
        argv = c["argv"]
        name = os.path.basename(argv[0]) if argv else ""
        env = c["env"]
        if env is None:
            child_less = "<inherit>"
        else:
            child_less = repr(env["LESS"]) if "LESS" in env else "<absent>"
        written = "".join(c["stdin"].parts)
        parts.append(
            f"call{i}: cmd={name!r} params={argv[1:]!r} child_LESS={child_less} "
            f"ansi_kept={chr(27) in written} written={written!r}"
        )
    parts.append(f"parent_LESS_after={os.environ.get('LESS', '<absent>')!r}")
    parts.append(f"nullpager_out={FAKE_OUT.getvalue()!r}")
    print(" | ".join(parts))


LESS_VALUES = [
    UNSET,
    "",
    "-R",
    "R",
    "-r",
    "r",
    "-S",
    "-SR",
    "-FRX",
    "-X",
    "--RAW-CONTROL-CHARS",
    "--raw-control-chars",
    "--chop-long-lines",
    " ",
]
PAGERS = [
    "less",
    "less -R",
    "less -r",
    "less -S",
    "less --RAW-CONTROL-CHARS",
    "less -X -F",
]

for less in LESS_VALUES:
    for pager in PAGERS:
        run(less, pager, None)

# The less-detection branch only runs when color is None; also record the
# explicit-color paths for the "LESS unset" and "LESS empty" inputs.
for less in (UNSET, ""):
    for pager in ("less", "less -S"):
        for color in (True, False):
            run(less, pager, color)
